<?php $report=\App\Services\Seo::report($values,$section); ?>
<section class="seo-editor" id="seo-editor"><div class="editor-heading"><h2>SEO &amp; chia sẻ</h2><span class="badge">SEARCH APPEARANCE</span></div><p class="muted">Có thể dùng khóa dịch cho tiêu đề, mô tả và từ khóa. Canonical để trống sẽ tự tạo theo URL và ngôn ngữ. Gợi ý dưới đây hỗ trợ biên tập, không phải điểm xếp hạng Google.</p>
<div class="search-preview"><span><?=e(rtrim(config('app.url'),'/'))?> / <?=e($values['slug']??'duong-dan')?></span><h3 id="seo-preview-title"><?=e($report['title']?:'Tiêu đề hiển thị trên tìm kiếm')?></h3><p id="seo-preview-description"><?=e($report['description']?:'Nhập mô tả riêng, đúng nội dung và hữu ích cho người đọc.')?></p></div>
<?php foreach(\App\Services\Seo::FIELDS as $key=>$label):?><label><?=e($label)?><?php if(in_array($key,['robots_noindex','robots_nofollow'])):?><input type="checkbox" name="<?=e($key)?>" <?=!empty($values[$key])?'checked':''?>><?php elseif($key==='seo_description'):?><textarea name="<?=e($key)?>" rows="3" maxlength="500"><?=e($values[$key]??'')?></textarea><small id="seo-description-count"></small><?php else:?><input name="<?=e($key)?>" value="<?=e($values[$key]??'')?>" <?=$key==='seo_title'?'maxlength="200"':''?>><?php if($key==='seo_title'):?><small id="seo-title-count"></small><?php endif;?><?php endif;?></label><?php endforeach;?>
<details class="seo-checklist" open><summary>Gợi ý biên tập · <?=$report['words']?> từ trong nội dung</summary><ul><?php foreach($report['checks'] as [$label,$passed]):?><li><span class="<?=$passed?'check-pass':'check-warn'?>"><?=$passed?'✓':'○'?></span> <?=e($label)?></li><?php endforeach;?></ul><p class="muted">Đánh giá lại sau khi lưu. Độ dài tiêu đề/mô tả chỉ là khoảng tham khảo; Google có thể viết lại đoạn trích.</p></details></section>
